import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { GraphNode } from "../graph/types.js";
import type { GraphStore } from "../graph/store.js";
import type { ITsServerClient } from "./tsserver-client.js";

function markerNodeId(kind: "callers" | "implementations", symbolId: string): string {
  return `__meta__::resolver::${kind}::${symbolId}`;
}

function hasMarker(store: GraphStore, kind: "callers" | "implementations", symbol: GraphNode): boolean {
  const id = markerNodeId(kind, symbol.id);
  if (store.getNode(id) === null) return false;
  // After a file re-index the marker node survives but its outbound edge is deleted.
  // Only treat the marker as valid when the edge still points to the symbol.
  return store.getEdgesBySource(id).some((e) => e.target === symbol.id);
}

function setMarker(store: GraphStore, kind: "callers" | "implementations", symbol: GraphNode): void {
  const id = markerNodeId(kind, symbol.id);
  store.addNode({
    id,
    kind: "module",
    name: id,
    file: "__meta__/resolver",
    start_line: 1,
    end_line: 1,
    content_hash: "meta",
  });
  store.addEdge({
    source: id,
    target: symbol.id,
    kind: "imports",
    provenance: { source: "lsp", confidence: 1, evidence: `resolved:${kind}`, content_hash: "meta" },
    created_at: Date.now(),
  });
}

function findSymbolColumn(projectRoot: string, file: string, line: number, symbolName: string): number {
  try {
    const lines = readFileSync(join(projectRoot, file), "utf8").split(/\r?\n/);
    const idx = (lines[line - 1] ?? "").indexOf(symbolName);
    return idx >= 0 ? idx + 1 : 1;
  } catch {
    return 1;
  }
}

function unresolvedNameFromTarget(target: string): string | null {
  if (!target.startsWith("__unresolved__::")) return null;
  return target.slice("__unresolved__::".length).split(":")[0] ?? null;
}

function escapeRegex(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function signatureImplementsInterface(signature: string | undefined, interfaceName: string): boolean {
  if (!signature) return false;
  const rx = new RegExp(`\\bimplements\\b[^\\{]*\\b${escapeRegex(interfaceName)}\\b`);
  return rx.test(signature);
}

function classImplementsInterface(
  projectRoot: string,
  file: string,
  className: string,
  interfaceName: string,
  signature?: string,
): boolean {
  if (signature != null) {
    return signatureImplementsInterface(signature, interfaceName);
  }

  try {
    const content = readFileSync(join(projectRoot, file), "utf8");
    const rx = new RegExp(
      `\\bclass\\s+${escapeRegex(className)}\\b[^\\{]*\\bimplements\\b[^\\{]*\\b${escapeRegex(interfaceName)}\\b`,
      "m",
    );
    return rx.test(content);
  } catch {
    return false;
  }
}

export async function resolveMissingCallers(
  node: GraphNode,
  store: GraphStore,
  projectRoot: string,
  client: ITsServerClient,
): Promise<void> {
  if (hasMarker(store, "callers", node)) return;

  const col = findSymbolColumn(projectRoot, node.file, node.start_line, node.name);
  let refs;
  try {
    refs = await client.references(node.file, node.start_line, col);
  } catch (err) {
    // If tsserver is permanently unavailable (not installed), set the marker so we
    // don't retry on every symbol_graph call.  For transient failures (crash, timeout,
    // etc.) leave the marker unset so the next call can succeed.
    if (err instanceof Error && err.message.startsWith("TsServer failed to start:")) {
      setMarker(store, "callers", node);
    }
    // Do NOT create edges here — writing lsp-provenance edges from a name-match
    // fallback would misrepresent confidence; the existing unresolved tree-sitter
    // edges already capture the same information honestly.
    return;
  }
  for (const ref of refs) {
    const callerNode = store
      .getNodesByFile(ref.file)
      .find((n) => n.kind !== "module" && n.start_line <= ref.line && (n.end_line === null || n.end_line >= ref.line));
    if (!callerNode) continue;
    if (callerNode.id === node.id) continue; // self reference/declaration

    const exists = store.getEdgesBySource(callerNode.id).some((e) => e.kind === "calls" && e.target === node.id);
    if (exists) continue;
    store.addEdge({
      source: callerNode.id,
      target: node.id,
      kind: "calls",
      provenance: {
        source: "lsp",
        confidence: 0.9,
        evidence: `${ref.file}:${ref.line}:${ref.col}`,
        content_hash: callerNode.content_hash,
      },
      created_at: Date.now(),
    });
  }

  setMarker(store, "callers", node);
}


export async function resolveImplementations(
  node: GraphNode,
  store: GraphStore,
  projectRoot: string,
  client: ITsServerClient,
): Promise<void> {
  const syncDeclaredImplementations = () => {
    const declared = new Map<string, GraphNode>();
    const classFiles = new Set(store.listFiles());
    for (const row of store.queryRows<{ file: string }>("SELECT DISTINCT file FROM nodes WHERE kind = ?", ["class"])) {
      classFiles.add(row.file);
    }

    for (const file of classFiles) {
      for (const classNode of store.getNodesByFile(file).filter((n) => n.kind === "class")) {
        if (!classImplementsInterface(projectRoot, classNode.file, classNode.name, node.name, classNode.signature)) continue;
        declared.set(classNode.id, classNode);
        const exists = store
          .getEdgesBySource(classNode.id)
          .some((e) => e.kind === "implements" && e.target === node.id && e.provenance.source === "lsp");
        if (!exists) {
          store.addEdge({
            source: classNode.id,
            target: node.id,
            kind: "implements",
            provenance: {
              source: "lsp",
              confidence: 0.9,
              evidence: `${classNode.file}:${classNode.start_line}:1`,
              content_hash: classNode.content_hash,
            },
            created_at: Date.now(),
          });
        }
      }
    }

    for (const neighbor of store.getNeighbors(node.id, { direction: "in", kind: "implements" })) {
      if (neighbor.edge.provenance.source !== "lsp") continue;
      if (declared.has(neighbor.node.id)) continue;
      store.deleteEdge(neighbor.edge.source, neighbor.edge.target, neighbor.edge.kind, neighbor.edge.provenance.source);
    }
  };

  if (hasMarker(store, "implementations", node)) {
    syncDeclaredImplementations();
    return;
  }
  const col = findSymbolColumn(projectRoot, node.file, node.start_line, node.name);
  const addFallbackImplementations = () => {
    syncDeclaredImplementations();
    setMarker(store, "implementations", node);
  };
  let impls;
  try {
    impls = await client.implementations(node.file, node.start_line, col);
  } catch {
    addFallbackImplementations();
    return;
  }
  if (!impls || impls.length === 0) {
    addFallbackImplementations();
    return;
  }
  for (const implLoc of impls) {
    const implNode = store
      .getNodesByFile(implLoc.file)
      .find((n) => n.kind === "class" && n.start_line <= implLoc.line && (n.end_line === null || n.end_line >= implLoc.line));
    if (!implNode) continue;
    if (!classImplementsInterface(projectRoot, implNode.file, implNode.name, node.name, implNode.signature)) continue;
    const exists = store.getEdgesBySource(implNode.id).some((e) => e.kind === "implements" && e.target === node.id);
    if (exists) continue;
    store.addEdge({
      source: implNode.id,
      target: node.id,
      kind: "implements",
      provenance: {
        source: "lsp",
        confidence: 0.9,
        evidence: `${implLoc.file}:${implLoc.line}:${implLoc.col}`,
        content_hash: implNode.content_hash,
      },
      created_at: Date.now(),
    });
  }
  syncDeclaredImplementations();
  setMarker(store, "implementations", node);
}

export async function runAstGrepIndexStage(
  store: GraphStore,
  projectRoot: string,
  files: string[],
  scanFn: typeof runScan = runScan,
): Promise<number> {
  let errors = 0;
  if (files.length === 0) return errors;
  const bundledDir = fileURLToPath(new URL("../rules/", import.meta.url));
  const rules = loadRules({ bundledDir, projectRoot });
  for (const rule of rules) {
    const matches = await scanFn(projectRoot, rule, files);
    errors += applyRuleMatches(store, rule, matches);
  }
  return errors;
}

export function runCoverageIndexStage(store: GraphStore, projectRoot: string, coverageDir: string): void {
  const normalized = parseCoverageReports(projectRoot, coverageDir);
  const mapped = mapCoverageToNodes(store, normalized);
  const byReport = new Map<string, MappedCoverageRecord[]>();

  for (const record of mapped) {
    const group = byReport.get(record.reportFile) ?? [];
    group.push(record);
    byReport.set(record.reportFile, group);
  }

  const reportNames = [...byReport.keys()].sort((a, b) => a.localeCompare(b));
  for (const reportFile of reportNames) {
    const group = byReport.get(reportFile)!;
    const tests = group
      .filter((record) => record.node.kind === "test" || record.file.endsWith(".test.ts") || record.file.endsWith(".spec.ts"))
      .sort((a, b) => a.node.id.localeCompare(b.node.id));
    const production = group
      .filter((record) => record.node.kind !== "test" && !record.file.endsWith(".test.ts") && !record.file.endsWith(".spec.ts"))
      .sort((a, b) => a.file.localeCompare(b.file) || a.startLine - b.startLine || a.node.id.localeCompare(b.node.id));

    for (const testRecord of tests) {
      for (const prodRecord of production) {
        store.addEdge({
          source: prodRecord.node.id,
          target: testRecord.node.id,
          kind: "tested_by",
          provenance: {
            source: "coverage",
            confidence: 1,
            evidence: `${reportFile}:${testRecord.file}:${testRecord.startLine}`,
            content_hash: prodRecord.node.content_hash,
          },
          created_at: Date.now(),
        });
      }

      const trace: TestTraceRecord = {
        testNodeId: testRecord.node.id,
        steps: [
          { nodeId: testRecord.node.id, ordinal: 0, contentHash: testRecord.node.content_hash },
          ...production.map((record, index) => ({
            nodeId: record.node.id,
            ordinal: index + 1,
            contentHash: record.node.content_hash,
          })),
        ],
      };
      store.saveTestTrace(trace);
    }
  }
  try {
    store.markCoverageIndexed();
  } catch {
    // readonly DB or other write failure: leave sentinel unset
  }
}

function getCurrentHead(projectRoot: string): string | null {
  try {
    return execSync("git rev-parse HEAD", {
      cwd: projectRoot,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
  } catch {
    return null;
  }
}

export async function runGitCoChangeStage(
  store: GraphStore,
  projectRoot: string,
  options: GitCoChangeOptions = {},
): Promise<number> {
  let errors = 0;
  const head = getCurrentHead(projectRoot);
  if (!head) return errors;
  const lastHead = store.getFileHash(GIT_HEAD_KEY);
  if (lastHead === head) return errors;
  const oldEdges = store.queryRows<{ source: string; target: string }>(
    "SELECT source, target FROM edges WHERE kind = 'co_changes_with' AND provenance_source = 'git'",
  );
  for (const edge of oldEdges) {
    try {
      store.deleteEdge(edge.source, edge.target, "co_changes_with", "git");
    } catch {
      errors++;
    }
  }
  const minCount = options.minCoChangeCount ?? 2;
  const windowDays = options.windowDays ?? 365;
  const commits = parseGitLog(projectRoot);
  if (commits.length === 0) {
    try {
      store.setFileHash(GIT_HEAD_KEY, head);
    } catch {
      errors++;
    }
    return errors;
  }
  const now = Date.now();
  const halfLifeDays = windowDays / 4;
  const trackedFiles = new Set(store.listFiles());
  const pairCounts = new Map<string, { count: number; weightedScore: number }>();
  for (const commit of commits) {
    const relevantFiles = commit.files.filter((f) => trackedFiles.has(f)).sort();
    if (relevantFiles.length < 2) continue;
    const weight = computeDecayWeight(commit.dateIso, now, halfLifeDays);
    for (let i = 0; i < relevantFiles.length; i++) {
      for (let j = i + 1; j < relevantFiles.length; j++) {
        const key = `${relevantFiles[i]}|${relevantFiles[j]}`;
        const existing = pairCounts.get(key) ?? { count: 0, weightedScore: 0 };
        existing.count++;
        existing.weightedScore += weight;
        pairCounts.set(key, existing);
      }
    }
  }
  for (const [key, data] of pairCounts) {
    if (data.count < minCount) continue;
    const [fileA, fileB] = key.split("|");
    const nodeA = store.findNodes(fileA!)[0];
    const nodeB = store.findNodes(fileB!)[0];
    if (!nodeA || !nodeB) continue;
    const evidence = `co_changes: ${data.count}, recency_score: ${data.weightedScore.toFixed(1)}, window: ${windowDays}d`;
    try {
      store.addEdge({
        source: nodeA.id,
        target: nodeB.id,
        kind: "co_changes_with",
        provenance: {
          source: "git",
          confidence: Math.min(0.9, 0.3 + data.count * 0.1),
          evidence,
          content_hash: nodeA.content_hash,
        },
        created_at: Date.now(),
      });
    } catch {
      errors++;
    }
  }

  try {
    store.setFileHash(GIT_HEAD_KEY, head);
  } catch {
    errors++;
  }
  return errors;
}

export function symbolGraph(params: SymbolGraphParams): string {
  const { include } = params;
  const resolvedNodes = params.store.findNodes(params.name, params.file);
  const useNeighborhoodBase = (include ?? []).includes("neighborhood");
  const base = useNeighborhoodBase
    ? renderLegacyNeighborhoodBody(params)
